/**
 * The 6F action byte.
 */
sealed class Action {
    
    /**
     * `0x70`: read/query.
     */
    object Check : Action()
    
    
    /**
     * `0x71`: write/configure.
     */
    object Set : Action()
    
    
    /**
     * `0x80`: reply to a check (also used by a few phone→watch pushes).
     */
    object CheckResponse : Action()
    
    
    /**
     * `0x81`: reply to a set; the generic ack `01 81 [cmd, status]` uses it.
     */
    object SetResponse : Action()
    
    
    /**
     * Any other byte, kept verbatim.
     */
    data class Other(
        val `raw`: kotlin.UByte) : Action()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAction : FfiConverterRustBuffer<Action>{
    override fun read(buf: ByteBuffer): Action {
        return when(buf.getInt()) {
            1 -> Action.Check
            2 -> Action.Set
            3 -> Action.CheckResponse
            4 -> Action.SetResponse
            5 -> Action.Other(
                FfiConverterUByte.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Action): ULong = when(value) {
        is Action.Check -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Action.Set -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Action.CheckResponse -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Action.SetResponse -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Action.Other -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUByte.allocationSize(value.`raw`)
            )
        }
    }

    override fun write(value: Action, buf: ByteBuffer) {
        when(value) {
            is Action.Check -> {
                buf.putInt(1)
                Unit
            }
            is Action.Set -> {
                buf.putInt(2)
                Unit
            }
            is Action.CheckResponse -> {
                buf.putInt(3)
                Unit
            }
            is Action.SetResponse -> {
                buf.putInt(4)
                Unit
            }
            is Action.Other -> {
                buf.putInt(5)
                FfiConverterUByte.write(value.`raw`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





