/**
 * What a matcher made of one packet.
 */
sealed class MatchOutcome {
    
    /**
     * Not for this request.
     */
    object Ignored : MatchOutcome()
    
    
    /**
     * One more record of a multi-frame reply. `latest` holds just that
     * record, in the same response shape the completion will use.
     */
    data class Progress(
        val `received`: kotlin.UInt, 
        val `total`: kotlin.UInt, 
        val `latest`: io.github.danperks.normsdk.Response?) : MatchOutcome()
        
    {
        

        companion object
    }
    
    data class Complete(
        val `response`: io.github.danperks.normsdk.Response) : MatchOutcome()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeMatchOutcome : FfiConverterRustBuffer<MatchOutcome>{
    override fun read(buf: ByteBuffer): MatchOutcome {
        return when(buf.getInt()) {
            1 -> MatchOutcome.Ignored
            2 -> MatchOutcome.Progress(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterOptionalTypeResponse.read(buf),
                )
            3 -> MatchOutcome.Complete(
                FfiConverterTypeResponse.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MatchOutcome): ULong = when(value) {
        is MatchOutcome.Ignored -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is MatchOutcome.Progress -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`received`)
                + FfiConverterUInt.allocationSize(value.`total`)
                + FfiConverterOptionalTypeResponse.allocationSize(value.`latest`)
            )
        }
        is MatchOutcome.Complete -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeResponse.allocationSize(value.`response`)
            )
        }
    }

    override fun write(value: MatchOutcome, buf: ByteBuffer) {
        when(value) {
            is MatchOutcome.Ignored -> {
                buf.putInt(1)
                Unit
            }
            is MatchOutcome.Progress -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.`received`, buf)
                FfiConverterUInt.write(value.`total`, buf)
                FfiConverterOptionalTypeResponse.write(value.`latest`, buf)
                Unit
            }
            is MatchOutcome.Complete -> {
                buf.putInt(3)
                FfiConverterTypeResponse.write(value.`response`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





