sealed class SessionEvent {
    
    /**
     * Every decoded frame, with the request that consumed it, if any.
     */
    data class Received(
        val `packet`: io.github.danperks.normsdk.Packet, 
        val `message`: io.github.danperks.normsdk.WatchMessage, 
        val `consumedBy`: kotlin.ULong?) : SessionEvent()
        
    {
        

        companion object
    }
    
    /**
     * One more record of a sync; `latest` is just that record.
     */
    data class Progress(
        val `requestId`: kotlin.ULong, 
        val `received`: kotlin.UInt, 
        val `total`: kotlin.UInt, 
        val `latest`: io.github.danperks.normsdk.Response?) : SessionEvent()
        
    {
        

        companion object
    }
    
    data class Completed(
        val `requestId`: kotlin.ULong, 
        val `response`: io.github.danperks.normsdk.Response) : SessionEvent()
        
    {
        

        companion object
    }
    
    /**
     * No reply in time. `partial` holds collected records or the
     * documented empty result for probes.
     */
    data class TimedOut(
        val `requestId`: kotlin.ULong, 
        val `partial`: io.github.danperks.normsdk.Response?) : SessionEvent()
        
    {
        

        companion object
    }
    
    data class Cancelled(
        val `requestId`: kotlin.ULong) : SessionEvent()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSessionEvent : FfiConverterRustBuffer<SessionEvent>{
    override fun read(buf: ByteBuffer): SessionEvent {
        return when(buf.getInt()) {
            1 -> SessionEvent.Received(
                FfiConverterTypePacket.read(buf),
                FfiConverterTypeWatchMessage.read(buf),
                FfiConverterOptionalULong.read(buf),
                )
            2 -> SessionEvent.Progress(
                FfiConverterULong.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterOptionalTypeResponse.read(buf),
                )
            3 -> SessionEvent.Completed(
                FfiConverterULong.read(buf),
                FfiConverterTypeResponse.read(buf),
                )
            4 -> SessionEvent.TimedOut(
                FfiConverterULong.read(buf),
                FfiConverterOptionalTypeResponse.read(buf),
                )
            5 -> SessionEvent.Cancelled(
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SessionEvent): ULong = when(value) {
        is SessionEvent.Received -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePacket.allocationSize(value.`packet`)
                + FfiConverterTypeWatchMessage.allocationSize(value.`message`)
                + FfiConverterOptionalULong.allocationSize(value.`consumedBy`)
            )
        }
        is SessionEvent.Progress -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`requestId`)
                + FfiConverterUInt.allocationSize(value.`received`)
                + FfiConverterUInt.allocationSize(value.`total`)
                + FfiConverterOptionalTypeResponse.allocationSize(value.`latest`)
            )
        }
        is SessionEvent.Completed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`requestId`)
                + FfiConverterTypeResponse.allocationSize(value.`response`)
            )
        }
        is SessionEvent.TimedOut -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`requestId`)
                + FfiConverterOptionalTypeResponse.allocationSize(value.`partial`)
            )
        }
        is SessionEvent.Cancelled -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`requestId`)
            )
        }
    }

    override fun write(value: SessionEvent, buf: ByteBuffer) {
        when(value) {
            is SessionEvent.Received -> {
                buf.putInt(1)
                FfiConverterTypePacket.write(value.`packet`, buf)
                FfiConverterTypeWatchMessage.write(value.`message`, buf)
                FfiConverterOptionalULong.write(value.`consumedBy`, buf)
                Unit
            }
            is SessionEvent.Progress -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`requestId`, buf)
                FfiConverterUInt.write(value.`received`, buf)
                FfiConverterUInt.write(value.`total`, buf)
                FfiConverterOptionalTypeResponse.write(value.`latest`, buf)
                Unit
            }
            is SessionEvent.Completed -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`requestId`, buf)
                FfiConverterTypeResponse.write(value.`response`, buf)
                Unit
            }
            is SessionEvent.TimedOut -> {
                buf.putInt(4)
                FfiConverterULong.write(value.`requestId`, buf)
                FfiConverterOptionalTypeResponse.write(value.`partial`, buf)
                Unit
            }
            is SessionEvent.Cancelled -> {
                buf.putInt(5)
                FfiConverterULong.write(value.`requestId`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






