/**
 * What a received frame means.
 */
sealed class WatchMessage {
    
    /**
     * Generic ack `01 81 [command, status]`.
     */
    data class Ack(
        val `command`: kotlin.UByte, 
        val `status`: kotlin.UByte) : WatchMessage()
        
    {
        

        companion object
    }
    
    /**
     * Battery reply (`0x08`), new-mode encoding.
     */
    data class Battery(
        val `status`: io.github.danperks.normsdk.BatteryStatus) : WatchMessage()
        
    {
        

        companion object
    }
    
    /**
     * Patched battery stream (`E4 71 [level, state]`); state 2 = on charger.
     */
    data class BatteryStream(
        val `level`: kotlin.UByte, 
        val `onCharger`: kotlin.Boolean) : WatchMessage()
        
    {
        

        companion object
    }
    
    /**
     * Find phone (`D2 71 [00 start | 01 stop]`). Reply to a start with
     * `FindPhoneStartAck` on the remote channel.
     */
    data class FindPhone(
        val `ringing`: kotlin.Boolean) : WatchMessage()
        
    {
        

        companion object
    }
    
    data class MusicControl(
        val `action`: io.github.danperks.normsdk.MusicControl) : WatchMessage()
        
    {
        

        companion object
    }
    
    data class DeviceControl(
        val `action`: io.github.danperks.normsdk.DeviceControl) : WatchMessage()
        
    {
        

        companion object
    }
    
    data class PhoneGps(
        val `event`: io.github.danperks.normsdk.PhoneGpsEvent) : WatchMessage()
        
    {
        

        companion object
    }
    
    /**
     * Patched live workout heart rate (`E2 71 [bpm (cal_milli_le32)]`).
     */
    data class LiveHeartRate(
        val `bpm`: kotlin.UByte, 
        val `caloriesKcal`: kotlin.UInt?) : WatchMessage()
        
    {
        

        companion object
    }
    
    /**
     * Real-time heart rate (`0x5D`).
     */
    data class RealTimeHeartRate(
        val `bpm`: kotlin.UByte) : WatchMessage()
        
    {
        

        companion object
    }
    
    /**
     * A reminder sent by the watch after `GetReminders6e` (6E `0x11`).
     */
    data class Reminder6e(
        val `kind`: io.github.danperks.normsdk.ReminderKind, 
        val `hour`: kotlin.UByte, 
        val `minute`: kotlin.UByte, 
        val `weekdays`: kotlin.UByte) : WatchMessage()
        
    {
        

        companion object
    }
    
    /**
     * Anything else, usually a reply to a request.
     */
    data class Reply(
        val `command`: kotlin.UByte) : WatchMessage()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

