            10 -> WatchMessage.Reminder6e(
                FfiConverterTypeReminderKind.read(buf),
                FfiConverterUByte.read(buf),
                FfiConverterUByte.read(buf),
                FfiConverterUByte.read(buf),
                )
            11 -> WatchMessage.Reply(
                FfiConverterUByte.read(buf),
