    }

    override fun write(value: WatchMessage, buf: ByteBuffer) {
        when(value) {
            is WatchMessage.Ack -> {
                buf.putInt(1)
                FfiConverterUByte.write(value.`command`, buf)
                FfiConverterUByte.write(value.`status`, buf)
